<script setup lang="ts">
import { computed, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Plus, Search, MoreHorizontal, Users, ShieldCheck, ExternalLink } from 'lucide-vue-next';
import { Dialog, DialogContent, DialogTitle, DialogDescription } from '@/components/ui';
import { studio, authorize, disconnectAccount } from '@/services/studio';
import { uid } from '@/services/storage';
import { toast } from 'vue-sonner';
import type { TKAccount } from '@/types/studio';
const route = useRoute(); const router = useRouter();
const tab = computed(() => route.query.tab === 'groups' ? 'groups' : 'accounts');
const query = ref(''); const group = ref('all'); const status = ref('all'); const selected = ref<string[]>([]); const moveGroup = ref('ungrouped');
const accounts = computed(() => studio.value.accounts.filter(a => (group.value === 'all' || a.groupId === group.value) && (status.value === 'all' || a.status === status.value) && `${a.name} ${a.handle} ${a.note}`.toLowerCase().includes(query.value.toLowerCase())));
const authOpen = ref(false); const authStep = ref(0); const handle = ref(''); const authGroup = ref('ungrouped'); const scenario = ref('成功'); const error = ref('');
const editing = ref<TKAccount | null>(null); const disconnectId = ref(''); const groupName = ref(''); const groupEditId = ref(''); const deleteGroupId = ref(''); const more = ref(false);
const affected = computed(() => studio.value.tasks.filter(t => t.accountId === disconnectId.value && ['待发布', '已排期'].includes(t.status)).length);
function openAuth(account?: TKAccount) { handle.value = account?.handle ?? ''; authGroup.value = account?.groupId ?? 'ungrouped'; authStep.value = 0; error.value = ''; scenario.value = '成功'; authOpen.value = true; }
function complete() { try { const a = authorize(handle.value, authGroup.value, scenario.value); authStep.value = 2; toast.success(`${a.name} 授权状态已更新`); } catch(e) { error.value = (e as Error).message; } }
function groupSave() { const name = groupName.value.trim(); if (!name) return; if (studio.value.groups.some(g => g.name === name && g.id !== groupEditId.value)) { toast.error('分组名称已存在'); return; } const g = studio.value.groups.find(g => g.id === groupEditId.value); if (g) g.name = name; else studio.value.groups.push({ id: uid(), name }); groupName.value = ''; groupEditId.value = ''; }
function removeGroup() { studio.value.accounts.filter(a => a.groupId === deleteGroupId.value).forEach(a => a.groupId = 'ungrouped'); studio.value.groups = studio.value.groups.filter(g => g.id !== deleteGroupId.value); deleteGroupId.value = ''; }
function move() { studio.value.accounts.filter(a => selected.value.includes(a.id)).forEach(a => a.groupId = moveGroup.value); selected.value = []; toast.success('已移动帐号'); }
function saveAccount() { if (!editing.value) return; const target = studio.value.accounts.find(a => a.id === editing.value!.id); if (target) Object.assign(target, editing.value); editing.value = null; toast.success('帐号资料已保存'); }
</script>
<template>
  <div class="space-y-6">
    <header class="flex items-start justify-between"><div><h1 class="text-xl font-semibold text-slate-900">帐号管理</h1><p class="mt-2 text-[13px] text-slate-400">连接 TikTok 帐号，让内容创作与发布顺畅衔接</p></div><div class="flex gap-2"><div class="relative"><button class="studio-btn" @click="more = !more"><MoreHorizontal class="h-4 w-4" />更多</button><div v-if="more" class="absolute right-0 top-12 z-10 w-48 rounded-xl border bg-white p-2 shadow-lg"><button class="w-full rounded-lg px-3 py-2 text-left text-xs hover:bg-sky-50" @click="router.push('/roxy')">Roxy 窗口管理 ↗</button></div></div><button class="studio-primary" @click="openAuth()"><Plus class="h-4 w-4" />添加 TK 帐号</button></div></header>
    <div class="grid grid-cols-3 gap-4"><div v-for="metric in [{label:'全部帐号',value:studio.accounts.length},{label:'授权有效',value:studio.accounts.filter(a=>a.status==='已授权').length},{label:'需要处理',value:studio.accounts.filter(a=>['授权过期','权限不足'].includes(a.status)).length}]" :key="metric.label" class="studio-card"><span class="text-xs text-slate-400">{{ metric.label }}</span><p class="mt-2 text-3xl font-semibold text-slate-800">{{ metric.value }}</p></div></div>
    <nav class="flex gap-2 border-b border-slate-100 pb-3"><button class="studio-tab" :class="tab==='accounts' && 'studio-active'" @click="router.replace({query:{tab:'accounts'}})">帐号列表</button><button class="studio-tab" :class="tab==='groups' && 'studio-active'" @click="router.replace({query:{tab:'groups'}})">分组管理</button></nav>
    <template v-if="tab==='accounts'">
      <div class="flex flex-wrap gap-3"><div class="relative w-64"><Search class="absolute left-3 top-3 h-4 w-4 text-slate-400" /><input v-model="query" class="studio-field pl-9" placeholder="搜索帐号、用户名、备注"></div><select v-model="group" class="studio-field !w-40" aria-label="分组筛选"><option value="all">全部分组</option><option v-for="g in studio.groups" :key="g.id" :value="g.id">{{ g.name }}</option></select><select v-model="status" class="studio-field !w-40" aria-label="状态筛选"><option value="all">全部授权状态</option><option>已授权</option><option>授权过期</option><option>权限不足</option><option>已解绑</option></select></div>
      <div v-if="selected.length" class="flex items-center gap-3 rounded-xl bg-sky-50 p-3 text-xs text-sky-700">已选 {{ selected.length }} 个帐号<select v-model="moveGroup" class="studio-field !w-40"><option v-for="g in studio.groups" :key="g.id" :value="g.id">{{g.name}}</option></select><button class="studio-btn" @click="move">移动分组</button></div>
      <div class="overflow-auto rounded-2xl border border-slate-200"><table class="studio-table"><thead><tr><th></th><th>帐号</th><th>分组 / 地区</th><th>授权状态</th><th>关联项目</th><th>授权时间</th><th>操作</th></tr></thead><tbody><tr v-for="a in accounts" :key="a.id"><td><input v-model="selected" type="checkbox" :value="a.id" :aria-label="`选择 ${a.name}`"></td><td><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-full bg-slate-900 font-semibold text-white">{{a.name.slice(0,1).toUpperCase()}}</span><div><p class="font-medium text-slate-800">{{a.name}}</p><p class="mt-1 text-[11px] text-slate-400">{{a.handle}} · TikTok</p><p v-if="a.note" class="mt-1 text-[11px]">{{a.note}}</p></div></div></td><td>{{studio.groups.find(g=>g.id===a.groupId)?.name}}<p class="mt-1 text-[11px] text-slate-400">{{a.region}}</p></td><td><span class="studio-badge" :class="a.status==='已授权' ? '!bg-emerald-50 !text-emerald-600' : '!bg-amber-50 !text-amber-600'">{{a.status}}</span></td><td>{{studio.projects.filter(p=>p.accountIds.includes(a.id)).map(p=>p.name).join('、') || '未关联'}}</td><td class="whitespace-nowrap">{{new Date(a.authorizedAt).toLocaleDateString()}}</td><td><div class="flex gap-3 whitespace-nowrap text-sky-600"><button @click="editing={...a}">编辑</button><button @click="openAuth(a)">重新授权</button><button v-if="a.status!=='已解绑'" class="text-slate-400" @click="disconnectId=a.id">解绑</button></div></td></tr></tbody></table><div v-if="!accounts.length" class="p-16 text-center text-sm text-slate-400"><Users class="mx-auto mb-3 h-9 w-9 text-slate-300" />暂无帐号，添加你的第一个 TikTok 帐号</div></div>
    </template>
    <template v-else><div class="flex max-w-xl gap-3"><input v-model="groupName" class="studio-field" placeholder="输入分组名称" maxlength="30" @keydown.enter="groupSave"><button class="studio-primary" @click="groupSave">{{groupEditId?'保存分组':'新建分组'}}</button><button v-if="groupEditId" class="studio-btn" @click="groupEditId='';groupName=''">取消</button></div><div class="grid grid-cols-3 gap-4"><div v-for="g in studio.groups" :key="g.id" class="studio-card"><h3 class="font-medium text-slate-800">{{g.name}}</h3><p class="my-4 text-sm text-slate-400">{{studio.accounts.filter(a=>a.groupId===g.id).length}} 个帐号</p><div v-if="g.id!=='ungrouped'" class="flex gap-4 text-xs text-sky-600"><button @click="groupEditId=g.id;groupName=g.name">重命名</button><button class="text-slate-400" @click="deleteGroupId=g.id">删除</button></div><p v-else class="text-xs text-slate-400">默认分组</p></div></div></template>
    <p class="text-[11px] text-slate-400">官方授权流程演示 · 本页面不会调用 TikTok 或保存真实令牌</p>
  </div>
  <Dialog :open="authOpen" @update:open="authOpen=$event"><DialogContent class="max-w-lg rounded-2xl bg-white p-7"><DialogTitle>连接 TikTok 帐号</DialogTitle><DialogDescription>通过官方授权连接帐号，发布前由你确认每条内容。</DialogDescription><div v-if="authStep===0" class="space-y-5"><div class="rounded-xl bg-sky-50 p-4 text-sm leading-7 text-sky-800"><ShieldCheck class="mb-2" />授权用于读取基本资料、发布内容及在独立授权允许的范围内读取内容数据。你可以随时解除绑定。</div><button class="studio-primary w-full" @click="authStep=1">前往 TikTok 授权（演示）<ExternalLink class="h-4 w-4" /></button></div><div v-else-if="authStep===1" class="space-y-4"><p class="text-xs text-slate-400">模拟 TikTok 授权回调</p><label class="block"><span class="studio-label">TikTok 用户名</span><input v-model="handle" class="studio-field" placeholder="@your.brand"></label><label class="block"><span class="studio-label">所属分组</span><select v-model="authGroup" class="studio-field"><option v-for="g in studio.groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label class="block"><span class="studio-label">演示结果</span><select v-model="scenario" class="studio-field"><option v-for="s in ['成功','拒绝','取消','过期','权限不足']" :key="s">{{s}}</option></select></label><p v-if="error" role="alert" class="text-xs text-rose-600">{{error}}</p><button class="studio-primary w-full" @click="complete">完成授权</button></div><div v-else class="py-6 text-center"><ShieldCheck class="mx-auto mb-4 h-12 w-12 text-emerald-500" /><h3 class="font-semibold">授权结果已保存</h3><p class="my-4 text-sm text-slate-400">下一步：在项目设置中关联帐号，开始发布。</p><button class="studio-primary" @click="authOpen=false">返回帐号列表</button></div></DialogContent></Dialog>
  <Dialog :open="!!editing" @update:open="!$event && (editing=null)"><DialogContent class="max-w-lg rounded-2xl bg-white p-6"><DialogTitle>编辑帐号资料</DialogTitle><DialogDescription>地区为运营填写信息，不代表平台认证地区。</DialogDescription><div v-if="editing" class="space-y-4"><label class="block"><span class="studio-label">昵称</span><input v-model="editing.name" class="studio-field"></label><label class="block"><span class="studio-label">运营地区（手动填写）</span><input v-model="editing.region" class="studio-field"></label><label class="block"><span class="studio-label">备注</span><input v-model="editing.note" class="studio-field"></label><label class="block"><span class="studio-label">分组</span><select v-model="editing.groupId" class="studio-field"><option v-for="g in studio.groups" :key="g.id" :value="g.id">{{g.name}}</option></select></label><button class="studio-primary" @click="saveAccount">保存</button></div></DialogContent></Dialog>
  <Dialog :open="!!disconnectId" @update:open="!$event && (disconnectId='')"><DialogContent class="max-w-md bg-white p-6"><DialogTitle>解除帐号绑定？</DialogTitle><DialogDescription>将暂停 {{affected}} 条待执行任务。历史发布和统计记录继续保留。</DialogDescription><button class="studio-primary" @click="disconnectAccount(disconnectId);disconnectId=''">确认解绑</button></DialogContent></Dialog>
  <Dialog :open="!!deleteGroupId" @update:open="!$event && (deleteGroupId='')"><DialogContent class="max-w-md bg-white p-6"><DialogTitle>删除分组？</DialogTitle><DialogDescription>分组内帐号会移入“未分组”，帐号与历史记录不会删除。</DialogDescription><button class="studio-primary" @click="removeGroup">确认删除分组</button></DialogContent></Dialog>
</template>
